import os
import re
from typing import Any, Dict, List, Optional, Tuple

import requests


class ContentSafetyError(RuntimeError):
    pass


def _azure_auth_headers(api_key: str) -> Dict[str, str]:
    return {
        "Content-Type": "application/json",
        "Ocp-Apim-Subscription-Key": api_key,
    }


def _call_azure_content_safety(endpoint: str, api_key: str, text: str) -> Dict[str, Any]:
    endpoint = endpoint.rstrip("/")
    url = f"{endpoint}/contentsafety/text:analyze?api-version=2023-10-01"
    payload = {
        "text": text,
        "categories": [
            "Hate",
            "SelfHarm",
            "Sexual",
            "Violence",
        ],
        "outputType": "FourSeverityLevels",
    }
    resp = requests.post(url, headers=_azure_auth_headers(api_key), json=payload, timeout=30)
    if resp.status_code >= 400:
        raise ContentSafetyError(f"Azure Content Safety request failed: {resp.status_code} {resp.text}")
    return resp.json()


def _severity_from_result(result: Dict[str, Any]) -> Dict[str, int]:
    categories = result.get("categoriesAnalysis", []) or []
    severities: Dict[str, int] = {}
    for item in categories:
        cat = item.get("category")
        sev = item.get("severity")
        if cat is not None and sev is not None:
            severities[str(cat).lower()] = int(sev)
    return severities


def _find_unsafe_spans(text: str) -> List[Tuple[int, int, str]]:
    patterns = [
        (r"\b(?:kill|murder|hang|shoot)\b", "violence"),
        (r"\b(?:suicide|self[-\s]?harm|cut myself|end my life)\b", "self_harm"),
        (r"\b(?:slur|hate speech)\b", "hate"),
        (r"\b(?:explicit sex|porn|nude|naked)\b", "sexual"),
    ]
    spans: List[Tuple[int, int, str]] = []
    lowered = text.lower()
    for pattern, label in patterns:
        for match in re.finditer(pattern, lowered):
            spans.append((match.start(), match.end(), label))
    spans.sort(key=lambda x: (x[0], x[1]))
    merged: List[Tuple[int, int, str]] = []
    for start, end, label in spans:
        if not merged or start > merged[-1][1]:
            merged.append((start, end, label))
        else:
            prev_start, prev_end, prev_label = merged[-1]
            merged[-1] = (prev_start, max(prev_end, end), prev_label)
    return merged


def redact_unsafe_spans(
    text: str,
    *,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
    redaction_token: str = "[REDACTED]",
) -> Dict[str, Any]:
    endpoint = endpoint or os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT", "")
    api_key = api_key or os.getenv("AZURE_CONTENT_SAFETY_KEY", "")
    if not endpoint or not api_key:
        raise ContentSafetyError(
            "Missing Azure Content Safety credentials. Set AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY."
        )

    analysis = _call_azure_content_safety(endpoint, api_key, text)
    severity_map = _severity_from_result(analysis)

    unsafe = any(sev >= 2 for sev in severity_map.values())
    spans: List[Tuple[int, int, str]] = []
    if unsafe:
        spans = _find_unsafe_spans(text)

    if not spans:
        return {
            "unsafe": unsafe,
            "redacted_text": text,
            "spans": [],
            "analysis": analysis,
        }

    out = []
    last = 0
    for start, end, label in spans:
        out.append(text[last:start])
        out.append(f"{redaction_token}")
        last = end
    out.append(text[last:])
    redacted_text = "".join(out)

    return {
        "unsafe": True,
        "redacted_text": redacted_text,
        "spans": [{"start": s, "end": e, "label": label} for s, e, label in spans],
        "analysis": analysis,
    }


def flag_or_redact_text(text: str, redact: bool = True) -> Dict[str, Any]:
    result = redact_unsafe_spans(text)
    if not redact:
        result["redacted_text"] = text
    return result
